// Tests trapping cfi-vcall with -fwhole-program-vtables on MS ABI calls
// through a secondary vfptr, where the overriding class and the class that
// owns the vfptr differ in LTO visibility.

struct Primary {
  virtual void pri();
};

struct [[clang::lto_visibility_public]] Public {
  virtual void pub();
};

struct DerivedFromPublic : Primary, Public {
  void pub() override;
};

struct HiddenSec {
  virtual void sec();
};

struct DerivedFromHidden : Primary, HiddenSec {
  void sec() override;
};

